H.background();
const cx = H.W*0.5, cy = H.H*0.55, R = 150;
// Arc subtended: from B (fixed) to C (controlled by slider P.arc, in degrees)
const aB = Math.PI*0.95;              // fixed left endpoint
const aC = aB - (P.arc*Math.PI/180);  // C swings clockwise by arc degrees
const Bx = cx + R*Math.cos(aB), By = cy + R*Math.sin(aB);
const Cx = cx + R*Math.cos(aC), Cy = cy + R*Math.sin(aC);
// Inscribed vertex P rides along the MAJOR arc (the part not between B,C); animate with t
const span = (Math.PI*2) - (aB - aC);          // major-arc angular length
const aP = aC - 0.15 - (0.7 + 0.25*Math.sin(t*0.7)) * (span - 0.3);
const Px = cx + R*Math.cos(aP), Py = cy + R*Math.sin(aP);
// circle + center
H.circle(cx, cy, R, { stroke: H.colors.grid, width: 2 });
H.circle(cx, cy, 4, { fill: H.colors.sub });
// highlight subtended minor arc B->C
const arcPts = [];
for (let i=0;i<=40;i++){ const a = aB + (aC-aB)*i/40; arcPts.push([cx+R*Math.cos(a), cy+R*Math.sin(a)]); }
H.path(arcPts, { color: H.colors.yellow, width: 6 });
// central angle (vertex = center)
H.line(cx, cy, Bx, By, { color: H.colors.accent, width: 2.5 });
H.line(cx, cy, Cx, Cy, { color: H.colors.accent, width: 2.5 });
// inscribed angle (vertex = P)
H.line(Px, Py, Bx, By, { color: H.colors.accent2, width: 2.5 });
H.line(Px, Py, Cx, Cy, { color: H.colors.accent2, width: 2.5 });
H.circle(Bx, By, 5, { fill: H.colors.yellow });
H.circle(Cx, Cy, 5, { fill: H.colors.yellow });
H.circle(Px, Py, 6, { fill: H.colors.accent2 });
const central = P.arc;          // degrees
const inscribed = central/2;
H.text("Inscribed angle = half the central angle", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Same arc (yellow): blue central is twice the orange inscribed.", 24, 52, { color: H.colors.sub, size: 13 });
H.text("central = " + central.toFixed(0) + " deg", 24, 80, { color: H.colors.accent, size: 14 });
H.text("inscribed = " + inscribed.toFixed(1) + " deg (constant as the vertex moves)", 24, 100, { color: H.colors.accent2, size: 14 });
